SET client_encoding = 'UTF8';
BEGIN;

UPDATE articulos 
SET metadata = '{"areas": ["carácter", "sociabilidad", "corporalidad"], "lugares": ["Exterior", "Campo Abierto", "Bosque"], "cantidad": "24 participantes", "duracion": "60 minutos", "unidades": ["manada", "compañía", "tropa"], "objetivos": ["Reforzar el desarrollo de los sentidos", "Estimular la observación", "Perder el miedo a la oscuridad", "Trabajo en equipo"], "materiales": ["Linterna", "Tarjetas", "Piedras", "Flauta"], "variaciones": "<b>Modalidad en Salón (Interior):</b> Se puede realizar en un gimnasio a oscuras utilizando instrumentos musicales para imitar los sonidos de la fauna. <b>Variante con pañolines:</b> Los animales pueden sujetar pañolines de colores para ser identificados visualmente al aproximarse.", "recomendaciones": "<b>Seguridad Nocturna:</b> Delimitar claramente las zonas de juego eliminando baches o alambres. Exigir el uso correcto del pañolín scout y verificar que cada grupo mantenga encendida su linterna de referencia al desplazarse.", "justificacion_areas": "Esta actividad de rastro y acecho nocturno ejercita tres áreas clave del desarrollo scout:\n\n1. <b>Carácter:</b> Desarrolla el autocontrol emocional, la valentía y la templanza al adentrarse en la vegetación a oscuras y acatar con honestidad las reglas del juego.\n\n2. <b>Sociabilidad:</b> Promueve el compromiso ambiental y la protección de la fauna salvaje al coordinar brigadas de patrulla para rescatar animales amenazados por cazadores furtivos.\n\n3. <b>Corporalidad:</b> Estimula la agudeza auditiva, la percepción sensorial y la agilidad física al rastrear señales sonoras sutiles y desplazarse con sigilo en el terreno.", "objetivos_educativos": [{"id": "041daaea-c4a7-472b-a613-951bd25cfa85", "area": "Carácter", "texto": "Reconozco y acepto mis errores.", "unidad": "Manada", "como_se_cumple": "Reconociendo mis desaciertos y acatando con fair play las reglas del intercambio de exploradores."}, {"id": "4df1ba93-06fe-4f49-b273-fddc3800cf17", "area": "Carácter", "texto": "Le doy importancia a las cosas que hago bien.", "unidad": "Manada", "como_se_cumple": "Valorando mi aporte al equipo al descifrar las señales sonoras de los animales escapados."}, {"id": "36d989b6-30dd-434a-874a-70a993ed0bec", "area": "Corporalidad", "texto": "Conozco las principales enfermedades que me pueden dar y por qué.", "unidad": "Manada", "como_se_cumple": "Cuidando mi bienestar físico e higiene al desplazarme con precaución por la vegetación a oscuras."}, {"id": "24addc27-b61b-44c5-ad5d-8bd12d1c4664", "area": "Corporalidad", "texto": "Arreglo mis problemas con mis compañeros sin usar la fuerza.", "unidad": "Manada", "como_se_cumple": "Resolviendo los desafíos de campo con diálogo y espíritu fraternal sin acudir a la brusquedad."}, {"id": "2cc128e0-7cc6-49df-a7c5-825f6ab79793", "area": "Carácter", "texto": "Sé que puedo ser cada día mejor.", "unidad": "Compañía", "como_se_cumple": "Superando el temor a la penumbra y demostrando autocrítica positiva en el avance de la patrulla."}, {"id": "006c5b09-47cf-4ed8-bf25-212203261a03", "area": "Carácter", "texto": "Sé que soy capaz de hacer cosas y de hacerlas bien.", "unidad": "Compañía", "como_se_cumple": "Confiando en mis capacidades de agudeza auditiva para guiar a mi equipo hacia las tarjetas de rescate."}, {"id": "0ba0d3c3-a50a-4a04-8981-601dc7746dd6", "area": "Corporalidad", "texto": "Sé lo que puedo y no puedo hacer con mi cuerpo.", "unidad": "Compañía", "como_se_cumple": "Regularizándome físicamente y manteniendo el equilibrio en terrenos boscosos accidentados."}, {"id": "52d9399a-4bf1-4010-a7ca-682b7d1c22a8", "area": "Corporalidad", "texto": "Trato de superar las dificultades físicas propias de mi crecimiento.", "unidad": "Compañía", "como_se_cumple": "Superando el cansancio muscular durante las carreras de acecho y búsqueda constante."}, {"id": "62876ebe-214f-4caf-b164-664e12fd30ae", "area": "Carácter", "texto": "Me gusta participar en actividades que me ayudan a conocerme.", "unidad": "Tropa", "como_se_cumple": "Participando con valentía y serenidad en la exploración nocturna para rescatar a los animales."}, {"id": "78bd48d3-5d26-4218-843a-33712bade630", "area": "Carácter", "texto": "Sé que soy capaz de hacer cosas y de hacerlas bien.", "unidad": "Tropa", "como_se_cumple": "Asumiendo el liderazgo táctico con humildad al orientar la patrulla por el origen del sonido."}, {"id": "36321046-051e-4c14-bb1e-7045faf4f5b4", "area": "Corporalidad", "texto": "Trato de no ser agresivo en juegos y actividades.", "unidad": "Tropa", "como_se_cumple": "Evitando brusquedades en los enfrentamientos y desplazándome en silencio por el matorral."}, {"id": "333453ab-e111-4f06-b0e3-a3e7f06b2439", "area": "Corporalidad", "texto": "Trato de superar las dificultades físicas propias de mi crecimiento.", "unidad": "Tropa", "como_se_cumple": "Demostrando agilidad corporal y templanza al reaccionar a las señales acústicas de la selva."}, {"id": "9593e059-a969-465e-9ebc-3a04a6d2bd63", "area": "Sociabilidad", "unidad": "Manada", "texto": "Conozco los principales árboles, plantas, animales, peces y aves de la región en que vivo.", "como_se_cumple": "Identificando y reconociendo la fauna nativa mediante las señales sonoras de los animales escapados."}, {"id": "03dceb73-d64f-46f6-994c-d5a2d7cbe9e3", "area": "Sociabilidad", "unidad": "Manada", "texto": "Conozco los principales animales y plantas de mi país que podrían desaparecer si no hacemos algo por ellos.", "como_se_cumple": "Comprendiendo la importancia de proteger las especies amenazadas de la selva frente a los cazadores furtivos."}, {"id": "658630b7-58fa-4ea9-8285-35ded35e3688", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco los diferentes ecosistemas de mi país.", "como_se_cumple": "Reconociendo los hábitos y hábitats naturales de los animales rescatados durante la exploración nocturna."}, {"id": "46017e67-80b2-4334-a154-3c2d0dfda7e3", "area": "Sociabilidad", "unidad": "Compañía", "texto": "He participado con mi patrulla en proyectos de conservación.", "como_se_cumple": "Coordinando con mi patrulla la búsqueda y rescate activo de la fauna silvestre en peligro."}, {"id": "39a993cd-7703-4757-8782-4f39d5e0dda2", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco los diferentes ecosistemas de mi país.", "como_se_cumple": "Identificando las características del bosque y protegiendo el entorno natural durante la búsqueda."}, {"id": "385a0c5c-c0c0-46f9-8294-95c7af828da5", "area": "Sociabilidad", "unidad": "Tropa", "texto": "He participado con mi patrulla en proyectos de conservación.", "como_se_cumple": "Liderando brigadas de rescate para resguardar a los animales y devolverlos a la reserva natural."}]}'::jsonb, updated_at = NOW() 
WHERE slug = 'el-rescate-en-la-selva-nocturna';

